// Soundscape catalogue: what each bed is, who may play it, which one suits a
// focus area at a given time of day, and the fade/duck level math. Pure,
// apart from the asset requires, which only run when a bed actually loads
// (so bun tests never touch the .m4a files). The files are generated by
// scripts/gen_soundscapes.py: original, procedural, sample-exact loops.

import type { FocusId } from "@/lib/focus";
import type { Daypart } from "@/lib/story/content/types";
import { BEDS, BED_IDS, BED_LEVELS, DEFAULT_BED, type BedId, type BedInfo } from "./types";

export interface Soundscape extends BedInfo {
  /** One line for the picker. */
  readonly blurb: string;
}

const BLURBS: Readonly<Record<BedId, string>> = {
  night: "A low, warm hum under an open sky, with a far chime now and then.",
  rain: "Soft rain against a window, close and steady.",
  hearth: "A slow fire, settling and crackling.",
  dawn: "Morning air, a gentle chord and the first birds.",
};

/** Picker order: the free bed first. */
export const SOUNDSCAPES: readonly Soundscape[] = BED_IDS.map((id) => ({ ...BEDS[id], blurb: BLURBS[id] }));

export function isBedLocked(id: BedId, isPlus: boolean): boolean {
  return BEDS[id].plus && !isPlus;
}

/** The profile's bed when it may play, else the free bed (a lapsed Plus bed falls back to 'night'). */
export function resolveBed(preferred: BedId | null | undefined, isPlus: boolean): BedId {
  return preferred && !isBedLocked(preferred, isPlus) ? preferred : DEFAULT_BED;
}

/** Suggested bed per focus × daypart: dawn light for mornings, rain for focus and calm, fire for warmth. */
export const SUGGESTED_BEDS: Readonly<Record<FocusId, Readonly<Record<Daypart, BedId>>>> = {
  love: { morning: "dawn", evening: "hearth" },
  abundance: { morning: "dawn", evening: "hearth" },
  career: { morning: "rain", evening: "rain" },
  health: { morning: "dawn", evening: "night" },
  confidence: { morning: "dawn", evening: "hearth" },
  peace: { morning: "rain", evening: "night" },
};

/** The bed to mark 'Suggested' in the picker. Free users are only ever offered the free bed. */
export function suggestedBed(focus: FocusId, daypart: Daypart, isPlus: boolean): BedId {
  return isPlus ? SUGGESTED_BEDS[focus][daypart] : DEFAULT_BED;
}

/** Metro asset id. Static requires so Metro bundles every bed; they only execute when called. */
export function bedAsset(id: BedId): number {
  switch (id) {
    case "night":
      return require("../../assets/audio/night.m4a");
    case "rain":
      return require("../../assets/audio/rain-on-glass.m4a");
    case "hearth":
      return require("../../assets/audio/hearth.m4a");
    case "dawn":
      return require("../../assets/audio/dawn.m4a");
  }
}

/** The one-second Star Birth chime (S4). */
export function starBirthChimeAsset(): number {
  return require("../../assets/audio/star-birth.m4a");
}

/* =========================================================================
 * Levels and fades
 * ========================================================================= */

export type BedLevel = keyof typeof BED_LEVELS;

/** Volume for a level, scaled by the caller's base volume and clamped to 0..1. */
export function bedVolume(level: BedLevel, base: number): number {
  return Math.min(1, Math.max(0, BED_LEVELS[level] * base));
}

/** Silence after an utterance before the bed comes back up to 'gap', so it
 * does not pump between sentences; real pauses (pause, finish) still lift it. */
export const DUCK_RELEASE_MS = 1200;

/** Exponent that maps amplitude to perceived loudness (Stevens' power law for sound). */
const LOUDNESS_EXPONENT = 0.6;

/**
 * Volume at `progress` (0..1) of a fade from `from` to `to`, linear in
 * perceived loudness rather than amplitude, so fades sound even: a fade-out
 * does not seem to hang and then drop, and a fade-in does not jump.
 */
export function fadeLevel(from: number, to: number, progress: number): number {
  const p = Math.min(1, Math.max(0, progress));
  const a = Math.max(0, from) ** LOUDNESS_EXPONENT;
  const b = Math.max(0, to) ** LOUDNESS_EXPONENT;
  return (a + (b - a) * p) ** (1 / LOUDNESS_EXPONENT);
}

/* =========================================================================
 * Watching for someone else pausing the bed
 * ========================================================================= */

/**
 * iOS pauses expo-audio's players itself when the route drops (AirPods back
 * in the case, headphones pulled) or a call interrupts, but expo-speech hears
 * neither: the chapter would carry on, aloud, from the phone's speaker. The
 * bed is the canary. While it should be playing, the hook reads the player
 * every BED_WATCH_INTERVAL_MS; BED_WATCH_MISSES 'not playing' readings in a
 * row, after it was heard playing, mean the system paused it, and the reader
 * pauses the voice too. Buffering and loading never count, and a bed that
 * never started (web autoplay rules) never trips it.
 */
export interface BedWatch {
  readonly seenPlaying: boolean;
  readonly misses: number;
}

export const BED_WATCH_START: BedWatch = { seenPlaying: false, misses: 0 };
export const BED_WATCH_INTERVAL_MS = 1000;
export const BED_WATCH_MISSES = 2;

export interface BedReading {
  readonly playing: boolean;
  readonly buffering: boolean;
  readonly loaded: boolean;
}

/** One reading of the player. Pure. `interrupted` is true on the reading that trips the watch. */
export function watchBed(prev: BedWatch, reading: BedReading): { readonly watch: BedWatch; readonly interrupted: boolean } {
  if (reading.playing) return { watch: { seenPlaying: true, misses: 0 }, interrupted: false };
  if (!prev.seenPlaying || reading.buffering || !reading.loaded) return { watch: { seenPlaying: prev.seenPlaying, misses: 0 }, interrupted: false };
  const misses = prev.misses + 1;
  return { watch: { seenPlaying: true, misses }, interrupted: misses === BED_WATCH_MISSES };
}
